 function showReservationPage(itemCount:number){setBookingError("");setUpsell(null);setCheckoutNavigationCount(current=>current+1);setShowCheckout(true);trackBookingFunnel(businessSlug,"booking_started",{metadata:{item_count:itemCount,source_flow:flowSource,date}});}
 function handleCartButtonClick(event:{preventDefault():void;stopPropagation():void}){event.preventDefault();event.stopPropagation();openCheckout();}
 function reserveItem(item:Item){noteInventoryInteraction(item,"reserve");if(!date){setAvailabilityItemId(item.id);setFocusedItemId(item.id);setBookingError("Choose your party date first.");focusDatePicker("rental_first");return;}if(available(item)<=0){setBookingError(`${item.name} is unavailable ${eventDateLabel}. Choose another date or a similar rental.`);trackBookingFunnel(businessSlug,"rental_unavailable",{inventoryItemId:item.id,metadata:{date,source_flow:flowSource}});return;}setBookingError("");setPartyNotice(`Added ${item.name} to your party.`);setFocusedItemId(null);trackBookingFunnel(businessSlug,"reserve_clicked",{inventoryItemId:item.id,metadata:{date,source_flow:flowSource}});setQuantities(current=>({...current,[item.id]:Math.max(1,current[item.id]??1)}));trackBookingFunnel(businessSlug,"item_added_to_cart",{inventoryItemId:item.id,metadata:{date,source_flow:flowSource}});}
 function openCheckout(){if(!selected.length){setBookingError("Add at least one rental to your party before checking out.");setShowCheckout(false);return;}const suggestion=findSuggestedUpsell({ignoreDismissed:true});if(suggestion){pendingUpsellAction.current="checkout";setUpsell(suggestion);return;}showReservationPage(selected.length);}
 useEffect(()=>{setAppliedPromo(null);setPromoError("");},[subtotal]);
 async function applyPromo(){if(!promoCode.trim()){setPromoError("Enter a promo code.");return;}setApplyingPromo(true);setPromoError("");try{const email=checkoutRef.current?.querySelector<HTMLInputElement>('input[name="email"]')?.value??"";const response=await fetch("/api/checkout/promo",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({businessSlug,code:promoCode,email,rentalDate:date,rentalEndDate:endDate,startTime,endTime,items:selected.map(item=>({inventoryItemId:item.id,quantity:quantities[item.id]})),operators:selected.map(item=>({inventoryItemId:item.id,selected:item.operator_mode==="required"?true:operatorFor(item)}))})});const result=await response.json();if(!response.ok)throw new Error(result.error||"Promo code could not be applied.");setAppliedPromo(result);setPromoCode(result.code);}catch(error){setAppliedPromo(null);setPromoError(error instanceof Error?error.message:"Promo code could not be applied.");}finally{setApplyingPromo(false);}}
 async function completeBooking(data:FormData,addedItem?:Item){if(!date||!endDate||!startTime||!endTime){setBookingError("Choose the rental start and end first.");return;}const bookingItems=addedItem&&!selected.some(item=>item.id===addedItem.id)?[...selected,addedItem]:selected;if(!bookingItems.length){setBookingError("Add at least one rental to your cart.");return;}const pricingError=bookingItems.map(priced).map(price=>"error" in price?price.error:null).find((error):error is string=>Boolean(error));if(pricingError){setBookingError(pricingError);return;}trackBookingFunnel(businessSlug,"customer_info_entered",{metadata:{item_count:bookingItems.length,source_flow:flowSource,date}});setBookingError("");setSubmitting(true);try{const response=await fetch("/api/checkout",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({...Object.fromEntries(data),promoCode:appliedPromo?.code??"",businessSlug,attributionSessionId:attributionSessionId||bookingAttributionSession(businessSlug),rentalDate:date,rentalEndDate:endDate,startTime,endTime,items:bookingItems.map(item=>({inventoryItemId:item.id,quantity:item.id===addedItem?.id?1:quantities[item.id]})),operators:bookingItems.map(item=>({inventoryItemId:item.id,selected:item.operator_mode==="required"?true:operatorFor(item)}))})});const result=await response.json();if(!response.ok)throw new Error(result.error||"The reservation could not be started.");if(result.paymentMode==="invoice_later"){setInvoiceLaterConfirmation(result.bookingNumber);setSubmitting(false);return;}trackBookingFunnel(businessSlug,"checkout_started",{metadata:{item_count:bookingItems.length,source_flow:flowSource,date}});if(window.top&&window.top!==window)window.top.location.href=result.url;else window.location.assign(result.url)}catch(error){setBookingError(error instanceof Error?error.message:"The reservation could not be started.");setSubmitting(false)}}
 function submit(data:FormData){setBookingError("");const suggestion=findSuggestedUpsell();if(!suggestion)return completeBooking(data);pendingBooking.current=data;pendingUpsellAction.current="submit";setUpsell(suggestion);}
 if(invoiceLaterConfirmation)return <section ref={confirmationRef} className="form-card rental-checkout booking-success" role="status" tabIndex={-1} aria-labelledby="rental-confirmation-title"><div className="success-check" aria-hidden="true">✓</div><small>Confirmation #{invoiceLaterConfirmation}</small><h2 id="rental-confirmation-title">Your reservation is confirmed</h2><p>{businessName} will send an invoice separately. No online payment was required to complete this booking.</p></section>;
 return <div className="party-rental-booking">
  {upsell&&<div className="rental-upsell-backdrop" role="presentation"><section ref={upsellRef} className="rental-upsell-dialog" role="dialog" aria-modal="true" aria-labelledby="rental-upsell-title" tabIndex={-1}>{upsell.image_url&&<img src={storageImageThumbUrl(upsell.image_url)??upsell.image_url} alt="" loading="lazy"/>}<span className="eyebrow">Suggested add-on</span><h2 id="rental-upsell-title">Add {upsell.name} for {money(upsell.daily_price_cents)}?</h2>{upsell.description&&<p>{upsell.description}</p>}<div><button ref={upsellPrimaryActionRef} type="button" className="button" onClick={()=>{setQuantity(upsell,1);dismissedUpsells.current.add(upsell.id);pendingBooking.current=null;pendingUpsellAction.current=null;showReservationPage(selected.length+1);}}>Add to cart and continue</button><button type="button" className="button secondary" onClick={()=>{dismissedUpsells.current.add(upsell.id);pendingBooking.current=null;pendingUpsellAction.current=null;showReservationPage(selected.length);}}>No thanks, continue booking</button></div></section></div>}
  <section className="rental-storefront-header"><div><span className="eyebrow">Book online</span><h1>Find the perfect rental for your party</h1><p>Browse everything, or choose your party date to see what&apos;s available.</p></div><div className="rental-storefront-date" ref={calendarRef} tabIndex={-1}>{date?<div className="rental-date-pill" role="status"><strong>Party date: {eventDateLabel}</strong><button type="button" className="text-button" onClick={()=>focusDatePicker("date_first")}>Change</button></div>:<small>You can still browse rentals before choosing a date.</small>}<section className="calendar" aria-label={availabilityItem?`Availability calendar for ${availabilityItem.name}`:"Choose your rental date"}><div className="calendar-head"><button type="button" aria-label="Previous month" disabled={viewDate<=currentMonth} onClick={()=>setViewDate(new Date(viewDate.getFullYear(),viewDate.getMonth()-1,1))}>‹</button><h3>{availabilityItem?.name??"Choose your dates"}<small>{viewDate.toLocaleDateString("en-US",{month:"long",year:"numeric"})}</small></h3><button type="button" aria-label="Next month" onClick={()=>setViewDate(new Date(viewDate.getFullYear(),viewDate.getMonth()+1,1))}>›</button></div><div className="weekdays" aria-hidden="true">{weekdays.map(day=><span key={day}>{day}</span>)}</div>{availabilityItem&&calendarAvailabilityLoading&&!activeCalendarAvailability?<div className="booking-calendar-skeleton" aria-label="Loading rental availability">{Array.from({length:35},(_,index)=><span key={index}/>)}</div>:<div className="days">{calendarDays.map((day,index)=>{if(!day)return <span className="day blank" key={`blank-${index}`}/>;const value=iso(year,month,day),dayAvailability=activeCalendarAvailability?.[value],isPast=value<todayIso,isStart=date===value,inRange=Boolean(date&&endDate&&value>date&&value<endDate),isEnd=endDate===value&&endDate!==date,blockedByCart=blockedDateSet.has(value),statusClass=isPast?"past":dayAvailability?.available===false?dayAvailability.reason==="blocked"?"blocked":"unavailable":blockedByCart?"blocked":"",disabled=isPast||dayAvailability?.available===false||(!availabilityItem&&blockedByCart);return <button type="button" key={value} className={`day ${statusClass}${isStart||isEnd?" selected":""}${inRange?" in-range":""}`} disabled={disabled} aria-label={`${value}${disabled?", unavailable":""}`} onClick={()=>{setDatePickerContext(availabilityItem?"item":"shopping");chooseCalendarDay(value);}}>{day}{dayAvailability?.available===false&&<small>{dayAvailability.reason==="blocked"?"Blocked":"Booked"}</small>}</button>;})}</div>}{calendarNotice&&<p className="rental-calendar-notice" role="status"><strong>{calendarNotice.startsWith("Unavailable")?"Unavailable":calendarNotice.startsWith("Past")?"Past date":"Availability"}</strong><span>{calendarNotice.replace(/^[^:]+:\s*/,"")}</span></p>}</section></div></section>
  <section className="booking-items-section"><div className="catalog-heading"><div>{date?<h2>{`Available rentals for ${pretty}`}</h2>:null}</div><div className="catalog-count">{selectedCount} in your party</div></div>
   <div className="rental-category-filter" aria-label="Rental categories">{categories.map(name=><button type="button" className={category===name?"active":""} aria-pressed={category===name} onClick={()=>setCategory(name)} key={name}>{name}</button>)}</div><label className="catalog-search"><span>Search rentals</span><input type="search" placeholder="Tables, chairs, bounce house…" value={search} onChange={e=>setSearch(e.target.value)}/></label>
   {partyNotice&&<div className="availability-banner" role="status"><span>✓</span><strong>{partyNotice}</strong><button type="button" onClick={()=>setPartyNotice("")}>Keep shopping</button></div>}
   <div className="inventory-gallery">{visible.map(item=>{const qty=quantities[item.id]??0,max=available(item),pricing=priced(item),statusLabel=!date?"Choose your party date, then add this to your party.":checkingAvailability?"Checking availability…":`✓ Available for ${eventDateLabel}`;return <article className={`inventory-card ${qty?"selected":""}${focusedItemId===item.id?" focused":""}`} key={item.id} onClick={()=>noteInventoryInteraction(item,"browse")}><div className="inventory-media">{item.image_url?<img src={storageImageThumbUrl(item.image_url)??item.image_url} alt={item.name} loading="lazy"/>:<div className="inventory-image-placeholder">Photo coming soon</div>}</div><div className="inventory-card-body"><span className="rental-card-category">{item.category||"Other rentals"}</span><div className="inventory-card-head"><h3>{item.name}</h3></div>{item.description&&<p>{item.description}</p>}<p className={`inventory-availability-status ${!date?"pending":"available"}`}>{statusLabel}</p><RentalPricingFooter priceCents={item.daily_price_cents} rentalHours={pricing.rules.standardRentalHours} multiDayMessage={rentalPricingMessage(pricing.rules)} unitSuffix={item.allow_quantity?" each":""} action={qty?<div className="quantity-picker-wrap"><div className="quantity-picker"><button type="button" onClick={()=>{noteInventoryInteraction(item,"adjust");setQuantity(item,qty-1);}} disabled={!qty}>−</button><div><strong>{qty}</strong><span>{date?`${Math.max(0,max)} available`:"In cart"}</span></div><button type="button" onClick={()=>{noteInventoryInteraction(item,"adjust");setQuantity(item,qty+1);}} disabled={date&&timeCapacity?qty>=max:false}>+</button></div><button type="button" className="catalog-inline-cart-button" onClick={handleCartButtonClick}>Go to cart</button></div>:<button type="button" className="catalog-add-button" onClick={()=>reserveItem(item)}>{`Add to Party — ${money(item.daily_price_cents)}`}</button>}/></div></article>})}{!visible.length&&<div className="empty-catalog"><h3>{date?"No rentals available that day":"No rentals available"}</h3><p>{date?"Choose another date or adjust your filters.":"Choose another category or clear your search."}</p></div>}</div>
  </section>
  {selected.length>0&&!showCheckout&&<section className="rental-booking-step rental-party-panel" aria-labelledby="party-panel-title"><div className="rental-party-panel-head"><div><span className="eyebrow">Your Party</span><h2 id="party-panel-title">{eventDateLabel||"Choose a party date when you’re ready"}</h2><p>{partyNotice||"Keep shopping, adjust quantities, or head to checkout when you’re ready."}</p></div><div className="catalog-count">{selectedCount} item{selectedCount===1?"":"s"}</div></div><div className="selected-summary">{selected.map(item=>{const price=priced(item),quantity=quantities[item.id]??0,operator=operatorPricing(item),additionalLabel=price.rules.additionalDayPricingType==="percentage_discount"?`${percentage(price.rules.additionalDayDiscountPercent)}% off`:price.rules.additionalDayPricingType==="flat_rate"?"flat additional-day rate":"standard rate";return <div className="rental-summary-item" key={item.id}><div className="summary-line"><span>{item.name} × {quantity}{price.rentalDays>1?` · ${price.rentalDays} days`:""}</span><strong>{money(price.totalUnitPriceCents*quantity)}</strong></div><div className="rental-day-breakdown"><div className="summary-line"><span>Day 1 · standard rental period{quantity>1?` · ${money(price.baseUnitPriceCents)} each`:""}</span><strong>{money(price.baseUnitPriceCents*quantity)}</strong></div>{Array.from({length:Math.max(0,price.rentalDays-1)},(_,index)=><div className="summary-line" key={index}><span>Day {index+2} · {additionalLabel}{quantity>1?` · ${money(price.additionalDayUnitPriceCents)} each`:""}</span><strong>{money(price.additionalDayUnitPriceCents*quantity)}</strong></div>)}</div>{operator.selected&&<div className="summary-line rental-operator-summary"><span>Professional Operator · {operator.hours} hour{operator.hours===1?"":"s"} × {money(operator.rateCents)}/hour</span><strong>+{money(operator.chargeCents)}</strong></div>}</div>})}<div className="summary-line"><span>Subtotal</span><strong>{money(subtotal)}</strong></div>{appliedPromo&&<div className="summary-line promo-applied"><span>{appliedPromo.name} ({appliedPromo.code})</span><strong>−{money(appliedPromo.discountCents)}</strong></div>}<div className="summary-total"><span>Total</span><strong>{money(total)}</strong></div></div><div className="rental-party-actions"><button type="button" className="button secondary" onClick={()=>setFocusedItemId(null)}>Keep Shopping</button><button type="button" className="button" onClick={openCheckout}>Checkout</button></div></section>}
  {selected.some(item=>item.operator_mode&&item.operator_mode!=="none")&&<section className="rental-operator-options" aria-labelledby="operator-options-title"><span className="eyebrow">Operator</span><h2 id="operator-options-title">Professional operator</h2><p>Choose whether you would like an operator for your rental.</p>{selected.filter(item=>item.operator_mode&&item.operator_mode!=="none").map(item=>{const pricing=operatorPricing(item),required=item.operator_mode==="required",selectedOperator=operatorFor(item);return <fieldset key={item.id}><legend>{item.name}</legend><div className="rental-operator-choice-grid"><label className={selectedOperator?"selected":""}><input type="radio" name={`operator-${item.id}`} checked={selectedOperator} onChange={()=>setOperatorSelections(current=>({...current,[item.id]:true}))}/><span><strong>✓ Professional Operator{!required&&" — Recommended"}</strong><b>+{money(Number(item.operator_hourly_rate_cents??0))}/hour</b><small>We&apos;ll provide an operator for the full rental period.</small></span></label>{!required&&<label className={!selectedOperator?"selected":""}><input type="radio" name={`operator-${item.id}`} checked={!selectedOperator} onChange={()=>setOperatorSelections(current=>({...current,[item.id]:false}))}/><span><strong>No operator</strong><small>I&apos;ll operate the equipment myself.</small></span></label>}</div>{selectedOperator&&date&&startTime&&endTime&&<p className="rental-operator-preview" aria-live="polite">Professional Operator · {pricing.hours} hour{pricing.hours===1?"":"s"} × {money(pricing.rateCents)}/hour <strong>+{money(pricing.chargeCents)}</strong></p>}</fieldset>})}</section>}
  {showCheckout&&<form ref={checkoutRef} onInput={()=>setRequiredFieldsComplete(checkoutRef.current?.checkValidity()??false)} onChange={()=>setRequiredFieldsComplete(checkoutRef.current?.checkValidity()??false)} onSubmit={event=>{event.preventDefault();void submit(new FormData(event.currentTarget));}} className="form-card rental-checkout"><span className="eyebrow">Your Party</span><h2 ref={checkoutHeadingRef} tabIndex={-1}>Complete your reservation</h2><p className="booking-required-note"><span>*</span> Required fields</p>
   {date&&<div className="rental-event-summary"><strong>Your event</strong><span>{eventDateLabel}</span></div>}
   {cartConflictMessage&&<div className="booking-submit-error" role="alert">{cartConflictMessage}</div>}
   <div className="form-grid"><label><span className="booking-field-title">Arrival time <span className="booking-required" aria-hidden="true">*</span><span className="sr-only">(required)</span></span><select required aria-required="true" value={startTime} onChange={event=>chooseStart(event.target.value,date)}>{arrivalTimeOptions.map(option=><option value={option.value} key={option.value}>{option.label}</option>)}</select></label>{allowMultiDay&&<label><span className="booking-field-title">Last day of rental <span className="booking-required" aria-hidden="true">*</span><span className="sr-only">(required)</span></span><input type="date" required aria-required="true" min={date} value={endDate} onChange={event=>chooseEndDate(event.target.value)}/></label>}</div>
   <div className="selected-summary">{selected.map(item=>{const price=priced(item),quantity=quantities[item.id]??0,operator=operatorPricing(item),additionalLabel=price.rules.additionalDayPricingType==="percentage_discount"?`${percentage(price.rules.additionalDayDiscountPercent)}% off`:price.rules.additionalDayPricingType==="flat_rate"?"flat additional-day rate":"standard rate";return <div className="rental-summary-item" key={item.id}><div className="summary-line"><span>{item.name} × {quantity}{price.rentalDays>1?` · ${price.rentalDays} days`:""}</span><strong>{money(price.totalUnitPriceCents*quantity)}</strong></div><div className="rental-day-breakdown"><div className="summary-line"><span>Day 1 · standard rental period{quantity>1?` · ${money(price.baseUnitPriceCents)} each`:""}</span><strong>{money(price.baseUnitPriceCents*quantity)}</strong></div>{Array.from({length:Math.max(0,price.rentalDays-1)},(_,index)=><div className="summary-line" key={index}><span>Day {index+2} · {additionalLabel}{quantity>1?` · ${money(price.additionalDayUnitPriceCents)} each`:""}</span><strong>{money(price.additionalDayUnitPriceCents*quantity)}</strong></div>)}</div>{operator.selected&&<div className="summary-line rental-operator-summary"><span>Professional Operator · {operator.hours} hour{operator.hours===1?"":"s"} × {money(operator.rateCents)}/hour</span><strong>+{money(operator.chargeCents)}</strong></div>}</div>})}<div className="summary-line"><span>Subtotal</span><strong>{money(subtotal)}</strong></div>{appliedPromo&&<div className="summary-line promo-applied"><span>{appliedPromo.name} ({appliedPromo.code})</span><strong>−{money(appliedPromo.discountCents)}</strong></div>}<div className="summary-total"><span>{onlinePaymentsReady&&safeDepositPercent===100?"Total due now":"Total"}</span><strong>{money(total)}</strong></div>{onlinePaymentsReady&&deposit>0&&safeDepositPercent<100?<div className="summary-line"><span>{safeDepositPercent}% deposit due now</span><strong>{money(deposit)}</strong></div>:!onlinePaymentsReady?<div className="summary-line"><span>Payment</span><strong>Invoice will be sent later</strong></div>:null}</div>
   <div className="promo-code-box"><label><span>Promo code</span><input value={promoCode} onChange={event=>{setPromoCode(event.target.value);setPromoError("");}} disabled={Boolean(appliedPromo)} autoComplete="off"/></label>{appliedPromo?<button type="button" className="button secondary" onClick={()=>{setAppliedPromo(null);setPromoCode("");}}>Remove</button>:<button type="button" className="button secondary" onClick={()=>void applyPromo()} disabled={applyingPromo||!selected.length}>{applyingPromo?"Applying…":"Apply"}</button>}{promoError&&<small role="alert">{promoError}</small>}{appliedPromo&&<small role="status">You save {money(appliedPromo.discountCents)}.</small>}</div>
   <div className="form-grid"><label><span className="booking-field-title">First name <span className="booking-required" aria-hidden="true">*</span><span className="sr-only">(required)</span></span><input name="firstName" required aria-required="true"/></label><label><span className="booking-field-title">Last name <span className="booking-required" aria-hidden="true">*</span><span className="sr-only">(required)</span></span><input name="lastName" required aria-required="true"/></label><label><span className="booking-field-title">Email <span className="booking-required" aria-hidden="true">*</span><span className="sr-only">(required)</span></span><input name="email" type="email" required aria-required="true"/></label><label><span className="booking-field-title">Phone <span className="booking-required" aria-hidden="true">*</span><span className="sr-only">(required)</span></span><input name="phone" type="tel" required aria-required="true"/></label></div><label><span className="booking-field-title">Delivery address <span className="booking-required" aria-hidden="true">*</span><span className="sr-only">(required)</span></span><input name="address" required aria-required="true"/></label><div className="form-grid"><label><span className="booking-field-title">City <span className="booking-required" aria-hidden="true">*</span><span className="sr-only">(required)</span></span><input name="city" required aria-required="true"/></label><label><span className="booking-field-title">ZIP code <span className="booking-required" aria-hidden="true">*</span><span className="sr-only">(required)</span></span><input name="zipCode" required aria-required="true"/></label></div><label><span className="booking-field-title">Event notes <small>Optional</small></span><textarea name="notes" rows={3}/></label><label><span><input className="inline-checkbox" type="checkbox" name="agreementAccepted" value="true" required aria-required="true"/> I agree to the rental agreement and safety rules. <span className="booking-required" aria-hidden="true">*</span><span className="sr-only">(required)</span></span></label>{onlinePaymentsReady&&deposit>0&&<label><span><input className="inline-checkbox" type="checkbox" name="depositAccepted" value="true" required aria-required="true"/> I understand the deposit policy. <span className="booking-required" aria-hidden="true">*</span><span className="sr-only">(required)</span></span></label>}{bookingError&&<div className="booking-submit-error" role="alert">{bookingError}</div>}<div className="rental-party-actions"><button type="button" className="button secondary" onClick={()=>setShowCheckout(false)}>Keep Shopping</button><button className="button" disabled={submitting||!date||!startTime||!endTime||!selected.length||!requiredFieldsComplete||cartConflicts.length>0}>{submitting?(onlinePaymentsReady&&deposit>0?"Opening secure checkout…":"Booking…"):(onlinePaymentsReady&&deposit>0?`Book and pay ${money(deposit)} deposit`:"Book now · Invoice later")}</button></div><small>{onlinePaymentsReady&&deposit>0?`Your reservation is securely processed for ${businessName} through Servonas.`:`Your booking will be completed now and ${businessName} will send the invoice later.`}</small></form>}
  {selected.length>0&&!showCheckout&&<div className="selection-bar visible"><div><strong>Your Party</strong><span>{date?eventDateLabel:"Choose your date"} · {partySummaryLine}</span></div><button type="button" className="button" onClick={openCheckout}>View Party</button></div>}
 </div>
